insert into public.learning_courses (id, title, image, content) values ('html-course-for-beginners', 'HTML Course for Beginners', 'img/course-art.svg', $content${"id":"html-course-for-beginners","title":{"en":"HTML Course for Beginners","ru":"HTML для начинающих"},"description":{"en":"Build an accessible page with semantic elements, links and forms.","ru":"Создайте доступную страницу с семантическими элементами, ссылками и формами."},"icon":"</>","minutes":60,"version":1,"lessons":[{"title":{"en":"Document structure","ru":"Структура документа"},"paragraphs":[{"en":"HTML describes the meaning and structure of content. A tag such as <h1> marks a heading; it does not execute a program.","ru":"HTML описывает смысл и структуру содержимого. Тег <h1> обозначает заголовок, а не выполняет программу."},{"en":"Start with a doctype, set the page language, and place metadata in head and visible content in body. Use one main heading to identify the page.","ru":"Начните с doctype, укажите язык страницы. Метаданные находятся в head, а видимое содержимое — в body. Главный заголовок обозначает тему страницы."}],"code":"<!doctype html>\n<html lang=\"ru\">\n<head><meta charset=\"utf-8\"><title>My page</title></head>\n<body><h1>Hello!</h1><p>My first page.</p></body>\n</html>","task":{"en":"Save this example as index.html. Open it in a browser and change the heading and the tab title.","ru":"Сохраните пример как index.html. Откройте его в браузере и измените заголовок и название вкладки."},"quiz":{"question":{"en":"Where does visible page content belong?","ru":"Где находится видимое содержимое страницы?"},"options":[{"en":"head","ru":"head"},{"en":"body","ru":"body"},{"en":"meta","ru":"meta"}],"explanation":{"en":"body contains the visible document; head contains metadata.","ru":"body содержит видимый документ, а head — метаданные."}}},{"title":{"en":"Links and semantic layout","ru":"Ссылки и семантика"},"paragraphs":[{"en":"Use a with href for links. Use nav for navigation, main for primary content, and footer for supporting information.","ru":"Для ссылок используйте a с href. nav обозначает навигацию, main — основное содержимое, footer — дополнительную информацию."},{"en":"An image needs alt text that describes its purpose. A decorative image should have an empty alt. Meaningful link text helps keyboard and screen reader users.","ru":"Атрибут alt описывает назначение изображения. Для декоративной картинки он пустой. Понятный текст ссылки помогает пользователям клавиатуры и программ чтения с экрана."}],"code":"<nav><a href=\"courses.html\">Courses</a></nav>\n<main><h1>Learning</h1><img src=\"diagram.svg\" alt=\"Three learning steps\"></main>\n<footer>SecretCoder</footer>","task":{"en":"Create navigation to two pages and add an image with a useful description.","ru":"Добавьте навигацию к двум страницам и изображение с понятным описанием."},"quiz":{"question":{"en":"Which attribute sets the destination of a link?","ru":"Какой атрибут задаёт адрес ссылки?"},"options":[{"en":"src","ru":"src"},{"en":"alt","ru":"alt"},{"en":"href","ru":"href"}],"explanation":{"en":"href sets the link destination; src loads a resource.","ru":"href задаёт адрес ссылки, src загружает ресурс."}}},{"title":{"en":"Forms and validation","ru":"Формы и проверка"},"paragraphs":[{"en":"A form groups fields that belong to one submission. Associate each label with an input using matching for and id values.","ru":"Форма объединяет поля для одной отправки. Свяжите label с input с помощью одинаковых значений for и id."},{"en":"type=\"email\" checks email format and required prevents empty submissions. Browser checks improve usability, but the server must validate submitted values too.","ru":"type=\"email\" проверяет формат почты, required запрещает пустое поле. Проверки браузера удобны, но сервер тоже должен проверять данные."}],"code":"<form>\n<label for=\"email\">Email</label>\n<input id=\"email\" name=\"email\" type=\"email\" required>\n<button type=\"submit\">Send</button>\n</form>","task":{"en":"Try submitting an empty email and an invalid email. Then add a required name field.","ru":"Попробуйте отправить пустую и некорректную почту. Затем добавьте обязательное поле имени."},"quiz":{"question":{"en":"What connects a label to an input?","ru":"Что связывает подпись с полем?"},"options":[{"en":"Matching for and id","ru":"Совпадающие for и id"},{"en":"The same CSS color","ru":"Одинаковый цвет CSS"},{"en":"A placeholder only","ru":"Только placeholder"}],"explanation":{"en":"The label for value must match the input id.","ru":"Значение for подписи должно совпадать с id поля."}}}],"exam":[{"question":{"en":"Where does visible page content belong?","ru":"Где находится видимое содержимое страницы?"},"options":[{"en":"head","ru":"head"},{"en":"body","ru":"body"},{"en":"meta","ru":"meta"}]},{"question":{"en":"Which attribute sets the destination of a link?","ru":"Какой атрибут задаёт адрес ссылки?"},"options":[{"en":"src","ru":"src"},{"en":"alt","ru":"alt"},{"en":"href","ru":"href"}]},{"question":{"en":"What connects a label to an input?","ru":"Что связывает подпись с полем?"},"options":[{"en":"Matching for and id","ru":"Совпадающие for и id"},{"en":"The same CSS color","ru":"Одинаковый цвет CSS"},{"en":"A placeholder only","ru":"Только placeholder"}]},{"question":{"en":"Which element represents the primary content?","ru":"Какой элемент обозначает основное содержимое?"},"options":[{"en":"main","ru":"main"},{"en":"nav","ru":"nav"},{"en":"head","ru":"head"}]},{"question":{"en":"Are browser checks sufficient for server input security?","ru":"Достаточно ли проверок браузера для защиты серверных данных?"},"options":[{"en":"Yes","ru":"Да"},{"en":"No, server validation is required","ru":"Нет, нужна серверная проверка"},{"en":"Only for email","ru":"Только для почты"}]}],"image":"img/course-art.svg"}$content$::jsonb) on conflict (id) do update set title=excluded.title, image=excluded.image, content=excluded.content;
insert into learning_private.answer_keys (course_id, lesson_answers, exam_answers) values ('html-course-for-beginners', '[[1],[2],[0]]'::jsonb, '[1,2,0,0,1]'::jsonb) on conflict (course_id) do update set lesson_answers=excluded.lesson_answers, exam_answers=excluded.exam_answers;
insert into public.learning_courses (id, title, image, content) values ('front-end-development-css', 'Front End Development-CSS', 'img/course-art.svg', $content${"id":"front-end-development-css","title":{"en":"Front End Development-CSS","ru":"Фронтенд-разработка: CSS"},"description":{"en":"Style a responsive card layout with selectors, the box model and Flexbox.","ru":"Оформите адаптивные карточки с помощью селекторов, блочной модели и Flexbox."},"icon":"{ }","minutes":60,"version":1,"lessons":[{"title":{"en":"Selectors and cascade","ru":"Селекторы и каскад"},"paragraphs":[{"en":"CSS applies presentation rules to HTML. A class selector starts with a dot, and an ID selector starts with #.","ru":"CSS задаёт оформление HTML. Селектор класса начинается с точки, идентификатора — с #."},{"en":"The cascade compares origin, importance, specificity and source order. With equal specificity, the later rule wins. Prefer reusable classes to excessive IDs.","ru":"Каскад учитывает источник, важность, специфичность и порядок. При одинаковой специфичности побеждает более позднее правило. Используйте повторно применяемые классы."}],"code":".card { color: #181d38; background: #fff; }\n.card { color: #334155; }","task":{"en":"Create a card class, then add a second rule and observe which color applies.","ru":"Создайте класс card, добавьте второе правило и посмотрите, какой цвет применяется."},"quiz":{"question":{"en":"Which selector targets class card?","ru":"Какой селектор выбирает класс card?"},"options":[{"en":"card","ru":"card"},{"en":".card","ru":".card"},{"en":"#card","ru":"#card"}],"explanation":{"en":"A dot selects a class.","ru":"Точка обозначает селектор класса."}}},{"title":{"en":"Box model","ru":"Блочная модель"},"paragraphs":[{"en":"Each element has content, padding, border and margin. Padding adds inner space; margin separates the element from its neighbors.","ru":"Элемент состоит из содержимого, внутренних отступов padding, рамки border и внешних отступов margin."},{"en":"With border-box, the specified width includes padding and border. This makes sizing more predictable. A max-width allows a card to shrink on small screens.","ru":"При border-box ширина включает padding и border. Размер становится предсказуемым, а max-width позволяет карточке сжиматься на небольших экранах."}],"code":"* { box-sizing: border-box; }\n.card { width: 100%; max-width: 360px; padding: 24px; border: 1px solid #ddd; margin: 16px; }","task":{"en":"Change padding and margin separately. Compare their effects using browser developer tools.","ru":"Измените padding и margin по отдельности. Сравните результат в инструментах разработчика."},"quiz":{"question":{"en":"What creates space inside the border?","ru":"Что создаёт отступ внутри рамки?"},"options":[{"en":"margin","ru":"margin"},{"en":"padding","ru":"padding"},{"en":"display","ru":"display"}],"explanation":{"en":"Padding is inner spacing; margin is outer spacing.","ru":"Padding — внутренний, margin — внешний отступ."}}},{"title":{"en":"Responsive Flexbox","ru":"Адаптивный Flexbox"},"paragraphs":[{"en":"Flexbox arranges items along a main axis. gap controls spacing and flex-wrap allows items to move onto new lines.","ru":"Flexbox размещает элементы вдоль основной оси. gap задаёт расстояние, flex-wrap разрешает перенос на следующую строку."},{"en":"A media query activates rules for matching screen conditions. Test both narrow and wide screens; do not assume a fixed desktop width.","ru":"Медиазапрос включает правила при заданных условиях экрана. Проверяйте узкие и широкие экраны, не ограничивайтесь шириной компьютера."}],"code":".grid { display: flex; flex-wrap: wrap; gap: 16px; }\n.card { flex: 1 1 260px; }\n@media (max-width: 600px) { .grid { flex-direction: column; } }","task":{"en":"Build three cards and resize the browser. Keep their text readable on a phone-width screen.","ru":"Создайте три карточки и изменяйте ширину окна. Убедитесь, что текст читается на ширине телефона."},"quiz":{"question":{"en":"Which property permits Flexbox items to wrap?","ru":"Какое свойство разрешает перенос элементов Flexbox?"},"options":[{"en":"flex-wrap","ru":"flex-wrap"},{"en":"font-size","ru":"font-size"},{"en":"z-index","ru":"z-index"}],"explanation":{"en":"flex-wrap: wrap enables new rows.","ru":"flex-wrap: wrap разрешает новые строки."}}}],"exam":[{"question":{"en":"Which selector targets class card?","ru":"Какой селектор выбирает класс card?"},"options":[{"en":"card","ru":"card"},{"en":".card","ru":".card"},{"en":"#card","ru":"#card"}]},{"question":{"en":"What creates space inside the border?","ru":"Что создаёт отступ внутри рамки?"},"options":[{"en":"margin","ru":"margin"},{"en":"padding","ru":"padding"},{"en":"display","ru":"display"}]},{"question":{"en":"Which property permits Flexbox items to wrap?","ru":"Какое свойство разрешает перенос элементов Flexbox?"},"options":[{"en":"flex-wrap","ru":"flex-wrap"},{"en":"font-size","ru":"font-size"},{"en":"z-index","ru":"z-index"}]},{"question":{"en":"What does border-box include in width?","ru":"Что входит в ширину при border-box?"},"options":[{"en":"Content only","ru":"Только содержимое"},{"en":"Content, padding and border","ru":"Содержимое, padding и border"},{"en":"All margins","ru":"Все margin"}]},{"question":{"en":"What applies different styles for a small screen?","ru":"Что применяет отдельные стили для маленького экрана?"},"options":[{"en":"A media query","ru":"Медиазапрос"},{"en":"An HTML comment","ru":"Комментарий HTML"},{"en":"An ID alone","ru":"Сам идентификатор"}]}],"image":"img/course-art.svg"}$content$::jsonb) on conflict (id) do update set title=excluded.title, image=excluded.image, content=excluded.content;
insert into learning_private.answer_keys (course_id, lesson_answers, exam_answers) values ('front-end-development-css', '[[1],[1],[0]]'::jsonb, '[1,1,0,1,0]'::jsonb) on conflict (course_id) do update set lesson_answers=excluded.lesson_answers, exam_answers=excluded.exam_answers;
insert into public.learning_courses (id, title, image, content) values ('introduction-to-javascript', 'Introduction to JavaScript', 'img/course-art.svg', $content${"id":"introduction-to-javascript","title":{"en":"Introduction to JavaScript","ru":"Введение в JavaScript"},"description":{"en":"Learn values, functions and DOM events by building a counter.","ru":"Изучите значения, функции и события DOM на примере счётчика."},"icon":"JS","minutes":60,"version":1,"lessons":[{"title":{"en":"Values and variables","ru":"Значения и переменные"},"paragraphs":[{"en":"JavaScript represents values such as strings, numbers and booleans. const prevents reassignment of a binding; let allows reassignment.","ru":"JavaScript работает со строками, числами и логическими значениями. const запрещает переназначение переменной, let разрешает."},{"en":"Use === for strict equality. It compares both type and value without converting a string into a number.","ru":"Используйте === для строгого равенства: оно сравнивает тип и значение без преобразования строки в число."}],"code":"const name = \"Alex\";\nlet count = 0;\ncount += 1;\nconsole.log(count === 1);","task":{"en":"Run the example in the browser console. Compare 1 === \"1\" and 1 == \"1\".","ru":"Запустите пример в консоли. Сравните 1 === \"1\" и 1 == \"1\"."},"quiz":{"question":{"en":"Which declaration allows reassignment?","ru":"Какое объявление разрешает переназначение?"},"options":[{"en":"const","ru":"const"},{"en":"let","ru":"let"},{"en":"Neither","ru":"Ни одно"}],"explanation":{"en":"let allows a new value to be assigned.","ru":"let разрешает присвоить новое значение."}}},{"title":{"en":"Functions and arrays","ru":"Функции и массивы"},"paragraphs":[{"en":"A function packages a reusable operation. Parameters receive input, and return gives the result back to the caller.","ru":"Функция объединяет повторно используемую операцию. Параметры принимают данные, return возвращает результат."},{"en":"Arrays store ordered values. map creates a new array by transforming each item; filter keeps items that satisfy a condition.","ru":"Массив хранит упорядоченные значения. map преобразует каждый элемент в новом массиве, filter сохраняет элементы по условию."}],"code":"function double(value) { return value * 2; }\nconst values = [1, 2, 3];\nconsole.log(values.map(double)); // [2, 4, 6]","task":{"en":"Write a function that adds 10, then map it over [1, 2, 3].","ru":"Напишите функцию, прибавляющую 10, и примените map к [1, 2, 3]."},"quiz":{"question":{"en":"What does map return?","ru":"Что возвращает map?"},"options":[{"en":"A new transformed array","ru":"Новый преобразованный массив"},{"en":"Always a number","ru":"Всегда число"},{"en":"Only the first item","ru":"Только первый элемент"}],"explanation":{"en":"map transforms every item and returns a new array.","ru":"map преобразует элементы и возвращает новый массив."}}},{"title":{"en":"DOM and events","ru":"DOM и события"},"paragraphs":[{"en":"The DOM represents the page as objects. querySelector finds an element using a CSS selector, and textContent changes its plain text.","ru":"DOM представляет страницу объектами. querySelector находит элемент по CSS-селектору, textContent меняет его текст."},{"en":"Use addEventListener to respond to clicks. In a form submit handler, preventDefault stops the browser navigation so your code can process the data.","ru":"addEventListener позволяет обрабатывать клики. В обработчике submit preventDefault останавливает переход браузера для обработки данных вашим кодом."}],"code":"const button = document.querySelector(\"button\");\nlet count = 0;\nbutton.addEventListener(\"click\", () => {\n count += 1;\n button.textContent = String(count);\n});","task":{"en":"Add a button to an HTML page and attach this counter. Add a reset button.","ru":"Добавьте кнопку на HTML-страницу и подключите счётчик. Создайте кнопку сброса."},"quiz":{"question":{"en":"Which method registers a click handler?","ru":"Какой метод регистрирует обработчик клика?"},"options":[{"en":"JSON.parse","ru":"JSON.parse"},{"en":"addEventListener","ru":"addEventListener"},{"en":"Array.map","ru":"Array.map"}],"explanation":{"en":"addEventListener registers an event callback.","ru":"addEventListener регистрирует функцию для события."}}}],"exam":[{"question":{"en":"Which declaration allows reassignment?","ru":"Какое объявление разрешает переназначение?"},"options":[{"en":"const","ru":"const"},{"en":"let","ru":"let"},{"en":"Neither","ru":"Ни одно"}]},{"question":{"en":"What does map return?","ru":"Что возвращает map?"},"options":[{"en":"A new transformed array","ru":"Новый преобразованный массив"},{"en":"Always a number","ru":"Всегда число"},{"en":"Only the first item","ru":"Только первый элемент"}]},{"question":{"en":"Which method registers a click handler?","ru":"Какой метод регистрирует обработчик клика?"},"options":[{"en":"JSON.parse","ru":"JSON.parse"},{"en":"addEventListener","ru":"addEventListener"},{"en":"Array.map","ru":"Array.map"}]},{"question":{"en":"What is the result of 1 === \"1\"?","ru":"Чему равно 1 === \"1\"?"},"options":[{"en":"true","ru":"true"},{"en":"false","ru":"false"},{"en":"\"1\"","ru":"\"1\""}]},{"question":{"en":"Which property safely inserts plain text?","ru":"Какое свойство безопасно вставляет обычный текст?"},"options":[{"en":"innerHTML","ru":"innerHTML"},{"en":"textContent","ru":"textContent"},{"en":"style","ru":"style"}]}],"image":"img/course-art.svg"}$content$::jsonb) on conflict (id) do update set title=excluded.title, image=excluded.image, content=excluded.content;
insert into learning_private.answer_keys (course_id, lesson_answers, exam_answers) values ('introduction-to-javascript', '[[1],[0],[1]]'::jsonb, '[1,0,1,1,1]'::jsonb) on conflict (course_id) do update set lesson_answers=excluded.lesson_answers, exam_answers=excluded.exam_answers;
insert into public.learning_courses (id, title, image, content) values ('python-programming', 'Python Programming', 'img/course-art.svg', $content${"id":"python-programming","title":{"en":"Python Programming","ru":"Программирование на Python"},"description":{"en":"Work with Python values, loops, functions and dictionaries.","ru":"Работайте со значениями Python, циклами, функциями и словарями."},"icon":"Py","minutes":60,"version":1,"lessons":[{"title":{"en":"Types and input","ru":"Типы и ввод"},"paragraphs":[{"en":"Python uses indentation to group statements. Values have types such as str, int, float and bool.","ru":"Python использует отступы для группировки команд. Значения имеют типы str, int, float и bool."},{"en":"input returns a string. Convert it with int or float before arithmetic, and handle invalid input when building a real program.","ru":"input возвращает строку. Перед вычислениями преобразуйте её через int или float; в программе нужно учитывать ошибочный ввод."}],"code":"age_text = \"20\"\nage = int(age_text)\nprint(age + 1) # 21","task":{"en":"Convert \"12.5\" to a float and multiply it by 2.","ru":"Преобразуйте \"12.5\" во float и умножьте на 2."},"quiz":{"question":{"en":"What type does input return?","ru":"Какой тип возвращает input?"},"options":[{"en":"int","ru":"int"},{"en":"str","ru":"str"},{"en":"bool","ru":"bool"}],"explanation":{"en":"input returns text even if the user types digits.","ru":"input возвращает текст, даже если введены цифры."}}},{"title":{"en":"Loops and lists","ru":"Циклы и списки"},"paragraphs":[{"en":"A list stores ordered items. A for loop visits each item, and an if statement runs a block only when a condition is true.","ru":"Список хранит упорядоченные элементы. Цикл for перебирает их, if выполняет блок при истинном условии."},{"en":"range(3) produces 0, 1 and 2. The stop value is excluded. Avoid changing a list while iterating over it.","ru":"range(3) даёт 0, 1 и 2: конечное значение не включается. Не изменяйте список во время его перебора."}],"code":"numbers = [2, 5, 8]\nfor number in numbers:\n    if number > 4:\n        print(number)","task":{"en":"Print only even numbers from [1, 2, 3, 4, 5, 6] using number % 2.","ru":"Выведите только чётные числа из [1, 2, 3, 4, 5, 6] с помощью number % 2."},"quiz":{"question":{"en":"Which values does range(3) produce?","ru":"Какие значения даёт range(3)?"},"options":[{"en":"1, 2, 3","ru":"1, 2, 3"},{"en":"0, 1, 2","ru":"0, 1, 2"},{"en":"0, 1, 2, 3","ru":"0, 1, 2, 3"}],"explanation":{"en":"range excludes its stop value.","ru":"range не включает конечное значение."}}},{"title":{"en":"Functions and dictionaries","ru":"Функции и словари"},"paragraphs":[{"en":"Define a function with def. return sends a result to the caller, while print only displays a value.","ru":"Функция объявляется через def. return передаёт результат вызывающему коду, print лишь выводит значение."},{"en":"A dictionary maps keys to values. Use get when a key may be absent, supplying a fallback to avoid a KeyError.","ru":"Словарь связывает ключи со значениями. Если ключ может отсутствовать, используйте get со значением по умолчанию."}],"code":"def greet(user):\n    return \"Hello, \" + user.get(\"name\", \"learner\")\n\nprint(greet({\"name\": \"Alex\"}))","task":{"en":"Write a function that receives a product dictionary and returns price multiplied by quantity.","ru":"Напишите функцию, которая принимает словарь товара и возвращает цену, умноженную на количество."},"quiz":{"question":{"en":"Which method reads an optional dictionary key?","ru":"Какой метод читает необязательный ключ словаря?"},"options":[{"en":"append","ru":"append"},{"en":"get","ru":"get"},{"en":"sort","ru":"sort"}],"explanation":{"en":"get supports a default when the key is absent.","ru":"get позволяет задать значение для отсутствующего ключа."}}}],"exam":[{"question":{"en":"What type does input return?","ru":"Какой тип возвращает input?"},"options":[{"en":"int","ru":"int"},{"en":"str","ru":"str"},{"en":"bool","ru":"bool"}]},{"question":{"en":"Which values does range(3) produce?","ru":"Какие значения даёт range(3)?"},"options":[{"en":"1, 2, 3","ru":"1, 2, 3"},{"en":"0, 1, 2","ru":"0, 1, 2"},{"en":"0, 1, 2, 3","ru":"0, 1, 2, 3"}]},{"question":{"en":"Which method reads an optional dictionary key?","ru":"Какой метод читает необязательный ключ словаря?"},"options":[{"en":"append","ru":"append"},{"en":"get","ru":"get"},{"en":"sort","ru":"sort"}]},{"question":{"en":"What groups a Python code block?","ru":"Что группирует блок кода Python?"},"options":[{"en":"Indentation","ru":"Отступы"},{"en":"HTML tags","ru":"HTML-теги"},{"en":"Only semicolons","ru":"Только точки с запятой"}]},{"question":{"en":"Which keyword returns a function result?","ru":"Какое слово возвращает результат функции?"},"options":[{"en":"print","ru":"print"},{"en":"return","ru":"return"},{"en":"input","ru":"input"}]}],"image":"img/course-art.svg"}$content$::jsonb) on conflict (id) do update set title=excluded.title, image=excluded.image, content=excluded.content;
insert into learning_private.answer_keys (course_id, lesson_answers, exam_answers) values ('python-programming', '[[1],[1],[1]]'::jsonb, '[1,1,1,0,1]'::jsonb) on conflict (course_id) do update set lesson_answers=excluded.lesson_answers, exam_answers=excluded.exam_answers;
insert into public.learning_courses (id, title, image, content) values ('sql-for-data-science', 'SQL for Data Science', 'img/course-art.svg', $content${"id":"sql-for-data-science","title":{"en":"SQL for Data Science","ru":"SQL для анализа данных"},"description":{"en":"Query, filter, group and join relational data.","ru":"Выбирайте, фильтруйте, группируйте и объединяйте данные."},"icon":"SQL","minutes":60,"version":1,"lessons":[{"title":{"en":"SELECT and filtering","ru":"SELECT и фильтрация"},"paragraphs":[{"en":"A relational table has rows and named columns. SELECT chooses columns, FROM chooses a table, and WHERE restricts rows.","ru":"Таблица состоит из строк и именованных столбцов. SELECT выбирает столбцы, FROM — таблицу, WHERE — строки по условию."},{"en":"ORDER BY controls result order. Without it, the database does not guarantee a particular row order. LIMIT caps the number of returned rows.","ru":"ORDER BY задаёт порядок результата. Без него определённый порядок строк не гарантирован. LIMIT ограничивает число строк."}],"code":"SELECT name, score\nFROM students\nWHERE score >= 80\nORDER BY score DESC\nLIMIT 10;","task":{"en":"Write a query that selects products costing less than 100, ordered by price.","ru":"Напишите запрос для товаров дешевле 100 с сортировкой по цене."},"quiz":{"question":{"en":"Which clause filters rows?","ru":"Какое выражение фильтрует строки?"},"options":[{"en":"WHERE","ru":"WHERE"},{"en":"ORDER BY","ru":"ORDER BY"},{"en":"SELECT","ru":"SELECT"}],"explanation":{"en":"WHERE checks a condition for each row.","ru":"WHERE проверяет условие для каждой строки."}}},{"title":{"en":"Aggregates and groups","ru":"Агрегаты и группы"},"paragraphs":[{"en":"COUNT counts rows, SUM totals values and AVG computes a mean. GROUP BY creates a group for each distinct grouping value.","ru":"COUNT считает строки, SUM суммирует значения, AVG вычисляет среднее. GROUP BY создаёт группы по значениям столбцов."},{"en":"WHERE filters rows before aggregation. HAVING filters groups after aggregation. COUNT(column) ignores NULL values; COUNT(*) counts rows.","ru":"WHERE фильтрует строки до агрегации, HAVING — группы после неё. COUNT(column) не учитывает NULL, COUNT(*) считает строки."}],"code":"SELECT category, COUNT(*) AS items, AVG(price) AS mean_price\nFROM products\nGROUP BY category\nHAVING COUNT(*) >= 2;","task":{"en":"Calculate total sales per city, keeping cities with more than five orders.","ru":"Посчитайте продажи по городам, оставив города с более чем пятью заказами."},"quiz":{"question":{"en":"Which clause filters aggregated groups?","ru":"Что фильтрует агрегированные группы?"},"options":[{"en":"LIMIT","ru":"LIMIT"},{"en":"HAVING","ru":"HAVING"},{"en":"FROM","ru":"FROM"}],"explanation":{"en":"HAVING applies conditions to grouped results.","ru":"HAVING применяет условия к группам."}}},{"title":{"en":"JOIN and NULL","ru":"JOIN и NULL"},"paragraphs":[{"en":"JOIN connects rows from different tables using matching keys. INNER JOIN returns matches; LEFT JOIN also keeps unmatched rows from the left table.","ru":"JOIN объединяет строки таблиц по ключам. INNER JOIN возвращает совпадения, LEFT JOIN сохраняет и строки левой таблицы без совпадений."},{"en":"NULL means an unknown or missing value. Use IS NULL instead of = NULL. Qualify column names when both tables have the same column name.","ru":"NULL обозначает неизвестное или отсутствующее значение. Используйте IS NULL вместо = NULL. Указывайте таблицу, если названия столбцов совпадают."}],"code":"SELECT s.name, c.title\nFROM students AS s\nLEFT JOIN courses AS c ON c.id = s.course_id\nWHERE c.id IS NULL;","task":{"en":"Explain which students this query returns. Rewrite it to return students with matched courses.","ru":"Объясните, каких учащихся возвращает запрос. Измените его для учащихся с найденным курсом."},"quiz":{"question":{"en":"Which join preserves unmatched left rows?","ru":"Какое объединение сохраняет строки слева без совпадения?"},"options":[{"en":"INNER JOIN","ru":"INNER JOIN"},{"en":"LEFT JOIN","ru":"LEFT JOIN"},{"en":"Only GROUP BY","ru":"Только GROUP BY"}],"explanation":{"en":"LEFT JOIN includes all left rows and NULL for missing right values.","ru":"LEFT JOIN сохраняет строки слева и ставит NULL при отсутствии данных справа."}}}],"exam":[{"question":{"en":"Which clause filters rows?","ru":"Какое выражение фильтрует строки?"},"options":[{"en":"WHERE","ru":"WHERE"},{"en":"ORDER BY","ru":"ORDER BY"},{"en":"SELECT","ru":"SELECT"}]},{"question":{"en":"Which clause filters aggregated groups?","ru":"Что фильтрует агрегированные группы?"},"options":[{"en":"LIMIT","ru":"LIMIT"},{"en":"HAVING","ru":"HAVING"},{"en":"FROM","ru":"FROM"}]},{"question":{"en":"Which join preserves unmatched left rows?","ru":"Какое объединение сохраняет строки слева без совпадения?"},"options":[{"en":"INNER JOIN","ru":"INNER JOIN"},{"en":"LEFT JOIN","ru":"LEFT JOIN"},{"en":"Only GROUP BY","ru":"Только GROUP BY"}]},{"question":{"en":"How should you test for a missing value?","ru":"Как проверить отсутствующее значение?"},"options":[{"en":"= NULL","ru":"= NULL"},{"en":"IS NULL","ru":"IS NULL"},{"en":"= 0","ru":"= 0"}]},{"question":{"en":"What guarantees the result order?","ru":"Что гарантирует порядок результата?"},"options":[{"en":"ORDER BY","ru":"ORDER BY"},{"en":"The physical table order","ru":"Физический порядок таблицы"},{"en":"COUNT(*)","ru":"COUNT(*)"}]}],"image":"img/course-art.svg"}$content$::jsonb) on conflict (id) do update set title=excluded.title, image=excluded.image, content=excluded.content;
insert into learning_private.answer_keys (course_id, lesson_answers, exam_answers) values ('sql-for-data-science', '[[0],[1],[1]]'::jsonb, '[0,1,1,1,0]'::jsonb) on conflict (course_id) do update set lesson_answers=excluded.lesson_answers, exam_answers=excluded.exam_answers;
insert into public.learning_courses (id, title, image, content) values ('chatgpt-for-beginners', 'ChatGPT for Beginners', 'img/course-art.svg', $content${"id":"chatgpt-for-beginners","title":{"en":"ChatGPT for Beginners","ru":"ChatGPT для начинающих"},"description":{"en":"Write clear prompts, review outputs and protect private information.","ru":"Формулируйте запросы, проверяйте ответы и защищайте личные данные."},"icon":"AI","minutes":60,"version":1,"lessons":[{"title":{"en":"Clear prompts","ru":"Понятные запросы"},"paragraphs":[{"en":"A useful prompt gives a goal, context, constraints and the expected output format. Include relevant source material rather than assuming the model knows your situation.","ru":"Полезный запрос содержит цель, контекст, ограничения и формат ответа. Добавляйте исходные материалы, не предполагая, что модель знает вашу ситуацию."},{"en":"Break a large task into smaller steps. Ask for a draft, inspect it and give specific feedback. A role description alone cannot guarantee accurate answers.","ru":"Разбивайте большую задачу на этапы. Попросите черновик, проверьте его и дайте конкретную обратную связь. Описание роли само по себе не гарантирует точность."}],"code":"Goal: summarize the supplied article.\nAudience: first-year students.\nConstraints: use only the article; flag missing facts.\nFormat: five bullets and one open question.","task":{"en":"Write a prompt for a study plan that includes your available time, level and learning goal.","ru":"Составьте запрос на учебный план с вашим временем, уровнем подготовки и целью."},"quiz":{"question":{"en":"Which prompt is most useful?","ru":"Какой запрос наиболее полезен?"},"options":[{"en":"Do something","ru":"Сделай что-нибудь"},{"en":"A goal with context and constraints","ru":"Цель с контекстом и ограничениями"},{"en":"Only a role name","ru":"Только название роли"}],"explanation":{"en":"Context and constraints make the requested result clearer.","ru":"Контекст и ограничения уточняют ожидаемый результат."}}},{"title":{"en":"Verification and uncertainty","ru":"Проверка и неопределённость"},"paragraphs":[{"en":"Generated text may contain factual errors or invented references. Fluent wording is not evidence that a claim is correct.","ru":"Сгенерированный текст может содержать ошибки и вымышленные ссылки. Убедительная формулировка не доказывает достоверность."},{"en":"Check important claims against original sources. Recalculate numerical results, open cited links, and distinguish quoted evidence from the model interpretation.","ru":"Проверяйте важные утверждения по первоисточникам. Пересчитывайте числа, открывайте ссылки и отличайте данные источника от интерпретации модели."}],"code":"Review checklist:\n1. Open the cited source.\n2. Find the claimed fact.\n3. Check dates and units.\n4. Recalculate numbers.","task":{"en":"Ask for an explanation of a topic you know and identify one claim that needs independent verification.","ru":"Попросите объяснить знакомую тему и найдите утверждение, требующее независимой проверки."},"quiz":{"question":{"en":"Does confident wording prove factual accuracy?","ru":"Доказывает ли уверенная формулировка точность?"},"options":[{"en":"Yes","ru":"Да"},{"en":"No","ru":"Нет"},{"en":"Only in a long answer","ru":"Только в длинном ответе"}],"explanation":{"en":"Accuracy must be checked using evidence.","ru":"Точность проверяется по подтверждающим данным."}}},{"title":{"en":"Privacy and safe workflows","ru":"Конфиденциальность и работа с данными"},"paragraphs":[{"en":"Do not paste passwords, API secrets or unnecessary personal data into prompts. Replace identifying details with placeholders before sharing examples.","ru":"Не вставляйте пароли, секретные API-ключи и лишние личные данные. Заменяйте идентифицирующие сведения условными значениями."},{"en":"Review generated code before running it. Instructions inside a document are part of that document, not automatically trusted commands. Keep a human review step before publishing or sending content.","ru":"Проверяйте код перед запуском. Инструкции внутри документа не становятся автоматически доверенными командами. Проверяйте материал перед публикацией или отправкой."}],"code":"Original: customer Jane, phone +..., order #...\nSanitized: customer A, phone [removed], order X\nTask: summarize the issue without identifying the person.","task":{"en":"Anonymize a sample support message and list which details you removed.","ru":"Обезличьте пример обращения в поддержку и перечислите удалённые сведения."},"quiz":{"question":{"en":"Which data should never be included in a prompt?","ru":"Какие данные нельзя включать в запрос?"},"options":[{"en":"A fictional example","ru":"Вымышленный пример"},{"en":"An API secret key","ru":"Секретный API-ключ"},{"en":"A public definition","ru":"Публичное определение"}],"explanation":{"en":"Secret keys must stay private.","ru":"Секретные ключи должны оставаться закрытыми."}}}],"exam":[{"question":{"en":"Which prompt is most useful?","ru":"Какой запрос наиболее полезен?"},"options":[{"en":"Do something","ru":"Сделай что-нибудь"},{"en":"A goal with context and constraints","ru":"Цель с контекстом и ограничениями"},{"en":"Only a role name","ru":"Только название роли"}]},{"question":{"en":"Does confident wording prove factual accuracy?","ru":"Доказывает ли уверенная формулировка точность?"},"options":[{"en":"Yes","ru":"Да"},{"en":"No","ru":"Нет"},{"en":"Only in a long answer","ru":"Только в длинном ответе"}]},{"question":{"en":"Which data should never be included in a prompt?","ru":"Какие данные нельзя включать в запрос?"},"options":[{"en":"A fictional example","ru":"Вымышленный пример"},{"en":"An API secret key","ru":"Секретный API-ключ"},{"en":"A public definition","ru":"Публичное определение"}]},{"question":{"en":"What should you do with a cited source?","ru":"Что нужно сделать с указанным источником?"},"options":[{"en":"Trust the title only","ru":"Доверять только заголовку"},{"en":"Open it and verify the claim","ru":"Открыть и проверить утверждение"},{"en":"Ignore it","ru":"Игнорировать"}]},{"question":{"en":"What should happen before running generated code?","ru":"Что нужно сделать перед запуском созданного кода?"},"options":[{"en":"Review the code","ru":"Проверить код"},{"en":"Share passwords","ru":"Передать пароли"},{"en":"Disable all checks","ru":"Отключить проверки"}]}],"image":"img/course-art.svg"}$content$::jsonb) on conflict (id) do update set title=excluded.title, image=excluded.image, content=excluded.content;
insert into learning_private.answer_keys (course_id, lesson_answers, exam_answers) values ('chatgpt-for-beginners', '[[1],[1],[1]]'::jsonb, '[1,1,1,1,0]'::jsonb) on conflict (course_id) do update set lesson_answers=excluded.lesson_answers, exam_answers=excluded.exam_answers;
insert into public.learning_courses (id, title, image, content) values ('aws-for-beginners', 'AWS for Beginners', 'img/course-art.svg', $content${"id":"aws-for-beginners","title":{"en":"AWS for Beginners","ru":"AWS для начинающих"},"description":{"en":"Understand cloud services, access control and cost planning without purchasing resources.","ru":"Разберитесь в облачных сервисах, доступе и расходах без покупки ресурсов."},"icon":"AWS","minutes":60,"version":1,"lessons":[{"title":{"en":"Cloud and service choices","ru":"Облако и выбор сервисов"},"paragraphs":[{"en":"Cloud computing provides on-demand resources. AWS offers compute, storage and managed databases; choose a service according to workload requirements.","ru":"Облачные вычисления предоставляют ресурсы по запросу. AWS предлагает вычисления, хранилища и управляемые базы; выбирайте сервис по потребностям задачи."},{"en":"EC2 supplies virtual machines, S3 stores objects, and RDS manages relational databases. Regions are geographic areas; availability zones isolate infrastructure within a region.","ru":"EC2 предоставляет виртуальные машины, S3 хранит объекты, RDS управляет реляционными базами. Регион — географическая область, зоны доступности разделяют инфраструктуру внутри региона."}],"code":"Website plan:\nStatic files -> object storage\nApplication server -> compute\nRelational records -> managed database","task":{"en":"Sketch a service plan for a small website. Explain why images and database records use different storage.","ru":"Составьте схему сервисов сайта. Объясните, почему изображения и записи базы используют разные хранилища."},"quiz":{"question":{"en":"Which service is designed for object storage?","ru":"Какой сервис предназначен для хранения объектов?"},"options":[{"en":"S3","ru":"S3"},{"en":"EC2","ru":"EC2"},{"en":"RDS","ru":"RDS"}],"explanation":{"en":"S3 stores objects, such as files and images.","ru":"S3 хранит объекты, например файлы и изображения."}}},{"title":{"en":"Identity and permissions","ru":"Учётные записи и разрешения"},"paragraphs":[{"en":"IAM controls access to AWS resources. Apply least privilege: grant only the actions and resources needed for a task.","ru":"IAM управляет доступом к ресурсам AWS. Принцип минимальных привилегий: разрешайте только необходимые действия и ресурсы."},{"en":"Use roles and temporary credentials for workloads where possible. Protect privileged accounts with MFA and never put access keys in public repositories.","ru":"По возможности используйте роли и временные данные доступа. Защищайте привилегированные аккаунты MFA и не публикуйте ключи в репозиториях."}],"code":"Permission review:\nWho needs access?\nWhich exact actions?\nWhich resources?\nHow long is access needed?","task":{"en":"Define minimum permissions for an application that only reads images from one bucket.","ru":"Определите минимальные разрешения для приложения, читающего изображения из одного бакета."},"quiz":{"question":{"en":"What does least privilege mean?","ru":"Что означает минимум привилегий?"},"options":[{"en":"Everyone is an administrator","ru":"Все администраторы"},{"en":"Only required permissions","ru":"Только необходимые разрешения"},{"en":"No passwords anywhere","ru":"Никаких паролей"}],"explanation":{"en":"Grant the smallest permission set needed for the task.","ru":"Разрешайте минимальный набор действий для задачи."}}},{"title":{"en":"Reliability and cost","ru":"Надёжность и расходы"},"paragraphs":[{"en":"The provider secures cloud infrastructure, while you remain responsible for your data, permissions and workload configuration. Responsibilities vary by service.","ru":"Провайдер защищает облачную инфраструктуру, вы отвечаете за данные, разрешения и настройки приложения. Разделение обязанностей зависит от сервиса."},{"en":"Estimate compute, storage and network charges before deployment. Budget alerts notify you but do not necessarily stop spending. Remove unused resources and test backup restoration.","ru":"Оцените расходы на вычисления, хранение и сеть до запуска. Уведомления о бюджете не обязательно останавливают траты. Удаляйте ненужные ресурсы и проверяйте восстановление резервных копий."}],"code":"Monthly estimate = compute + storage + requests + data transfer\nRecovery plan = backups + restore test + responsible owner","task":{"en":"Create a cost checklist for your website and describe how you would restore lost data.","ru":"Составьте список расходов сайта и опишите восстановление потерянных данных."},"quiz":{"question":{"en":"Does a budget alert always stop spending?","ru":"Всегда ли уведомление о бюджете останавливает расходы?"},"options":[{"en":"Yes","ru":"Да"},{"en":"No","ru":"Нет"},{"en":"Only for images","ru":"Только для изображений"}],"explanation":{"en":"An alert is a notification, not a guaranteed spending cap.","ru":"Уведомление не гарантирует ограничение расходов."}}}],"exam":[{"question":{"en":"Which service is designed for object storage?","ru":"Какой сервис предназначен для хранения объектов?"},"options":[{"en":"S3","ru":"S3"},{"en":"EC2","ru":"EC2"},{"en":"RDS","ru":"RDS"}]},{"question":{"en":"What does least privilege mean?","ru":"Что означает минимум привилегий?"},"options":[{"en":"Everyone is an administrator","ru":"Все администраторы"},{"en":"Only required permissions","ru":"Только необходимые разрешения"},{"en":"No passwords anywhere","ru":"Никаких паролей"}]},{"question":{"en":"Does a budget alert always stop spending?","ru":"Всегда ли уведомление о бюджете останавливает расходы?"},"options":[{"en":"Yes","ru":"Да"},{"en":"No","ru":"Нет"},{"en":"Only for images","ru":"Только для изображений"}]},{"question":{"en":"Who controls application access permissions?","ru":"Кто отвечает за разрешения приложения?"},"options":[{"en":"The customer","ru":"Клиент"},{"en":"Nobody","ru":"Никто"},{"en":"Only a browser","ru":"Только браузер"}]},{"question":{"en":"Why test restoring backups?","ru":"Зачем проверять восстановление копий?"},"options":[{"en":"To verify recovery works","ru":"Чтобы убедиться, что восстановление работает"},{"en":"To increase file sizes","ru":"Чтобы увеличить файлы"},{"en":"To publish access keys","ru":"Чтобы опубликовать ключи"}]}],"image":"img/course-art.svg"}$content$::jsonb) on conflict (id) do update set title=excluded.title, image=excluded.image, content=excluded.content;
insert into learning_private.answer_keys (course_id, lesson_answers, exam_answers) values ('aws-for-beginners', '[[0],[1],[1]]'::jsonb, '[0,1,1,0,0]'::jsonb) on conflict (course_id) do update set lesson_answers=excluded.lesson_answers, exam_answers=excluded.exam_answers;
insert into public.learning_courses (id, title, image, content) values ('microsoft-azure-essentials', 'Microsoft Azure Essentials', 'img/course-art.svg', $content${"id":"microsoft-azure-essentials","title":{"en":"Microsoft Azure Essentials","ru":"Основы Microsoft Azure"},"description":{"en":"Plan an Azure workload, permissions and operational monitoring.","ru":"Спланируйте приложение в Azure, разрешения и мониторинг."},"icon":"AZ","minutes":60,"version":1,"lessons":[{"title":{"en":"Azure resource structure","ru":"Структура ресурсов Azure"},"paragraphs":[{"en":"Azure resources belong to subscriptions and resource groups. A resource group organizes related resources so you can manage a workload together.","ru":"Ресурсы Azure относятся к подпискам и группам ресурсов. Группа объединяет связанные ресурсы для удобного управления приложением."},{"en":"Virtual Machines provide compute, Blob Storage stores objects, and Azure SQL Database is a managed relational database. Service choice depends on your application requirements.","ru":"Virtual Machines предоставляют вычисления, Blob Storage хранит объекты, Azure SQL Database — управляемая реляционная база. Выбирайте сервис под требования приложения."}],"code":"Subscription\n  Resource group: learning-site\n    Compute service\n    Blob storage\n    Managed database","task":{"en":"Draw a resource group for a study website and assign a purpose to each resource.","ru":"Нарисуйте группу ресурсов учебного сайта и назначение каждого ресурса."},"quiz":{"question":{"en":"What groups related Azure resources?","ru":"Что объединяет связанные ресурсы Azure?"},"options":[{"en":"A resource group","ru":"Группа ресурсов"},{"en":"A CSS class","ru":"Класс CSS"},{"en":"An email inbox","ru":"Почтовый ящик"}],"explanation":{"en":"A resource group is a management container.","ru":"Группа ресурсов — контейнер для управления."}}},{"title":{"en":"Identity and RBAC","ru":"Идентификация и RBAC"},"paragraphs":[{"en":"Microsoft Entra ID manages identities. Azure role-based access control assigns permissions to identities at a defined scope.","ru":"Microsoft Entra ID управляет идентификацией. RBAC назначает учётным записям разрешения в определённой области."},{"en":"Use the narrowest appropriate scope, such as one resource group. Managed identities let supported workloads authenticate without embedding passwords in application code.","ru":"Используйте минимальную область, например одну группу ресурсов. Управляемые идентификаторы позволяют приложениям входить без паролей в коде."}],"code":"Identity: reporting app\nRole: read-only\nScope: one resource group\nCredential approach: managed identity where supported","task":{"en":"Design read-only access for a reporting application. Explain why Owner is excessive.","ru":"Спланируйте доступ только для чтения приложению отчётов. Объясните, почему роль Owner избыточна."},"quiz":{"question":{"en":"What should determine an access scope?","ru":"Как нужно определять область доступа?"},"options":[{"en":"The minimum required resources","ru":"Минимально необходимые ресурсы"},{"en":"Every subscription by default","ru":"Все подписки по умолчанию"},{"en":"The logo color","ru":"Цвет логотипа"}],"explanation":{"en":"Limit access to resources required by the task.","ru":"Ограничивайте доступ ресурсами, нужными для задачи."}}},{"title":{"en":"Monitoring and budgets","ru":"Мониторинг и бюджет"},"paragraphs":[{"en":"Metrics track numerical signals such as request counts. Logs record events and details. Alerts notify an operator when a condition is met.","ru":"Метрики измеряют показатели, например количество запросов. Логи записывают события и детали. Оповещения сообщают о выполнении условия."},{"en":"Set a budget and examine actual usage. Plan backups and test recovery. Avoid creating paid resources just to follow this lesson; the exercise can be completed on paper.","ru":"Установите бюджет и контролируйте использование. Планируйте копии и проверяйте восстановление. Для этого урока не нужны платные ресурсы: задание можно выполнить на бумаге."}],"code":"Monitor: failed requests, latency, storage growth\nAlert: error rate above a chosen threshold\nRespond: inspect logs, fix, verify recovery","task":{"en":"Choose three signals to monitor for a website and one response to each alert.","ru":"Выберите три показателя сайта и действие при каждом оповещении."},"quiz":{"question":{"en":"Which source records detailed events?","ru":"Что записывает подробные события?"},"options":[{"en":"Logs","ru":"Логи"},{"en":"Only budgets","ru":"Только бюджеты"},{"en":"A page title","ru":"Заголовок страницы"}],"explanation":{"en":"Logs record event details for investigation.","ru":"Логи содержат детали событий для анализа."}}}],"exam":[{"question":{"en":"What groups related Azure resources?","ru":"Что объединяет связанные ресурсы Azure?"},"options":[{"en":"A resource group","ru":"Группа ресурсов"},{"en":"A CSS class","ru":"Класс CSS"},{"en":"An email inbox","ru":"Почтовый ящик"}]},{"question":{"en":"What should determine an access scope?","ru":"Как нужно определять область доступа?"},"options":[{"en":"The minimum required resources","ru":"Минимально необходимые ресурсы"},{"en":"Every subscription by default","ru":"Все подписки по умолчанию"},{"en":"The logo color","ru":"Цвет логотипа"}]},{"question":{"en":"Which source records detailed events?","ru":"Что записывает подробные события?"},"options":[{"en":"Logs","ru":"Логи"},{"en":"Only budgets","ru":"Только бюджеты"},{"en":"A page title","ru":"Заголовок страницы"}]},{"question":{"en":"Which service stores objects?","ru":"Какой сервис хранит объекты?"},"options":[{"en":"Blob Storage","ru":"Blob Storage"},{"en":"Entra ID","ru":"Entra ID"},{"en":"RBAC","ru":"RBAC"}]},{"question":{"en":"Why use a managed identity?","ru":"Зачем нужен управляемый идентификатор?"},"options":[{"en":"To avoid embedded credentials","ru":"Чтобы не хранить пароли в коде"},{"en":"To disable authentication","ru":"Чтобы отключить вход"},{"en":"To remove logs","ru":"Чтобы удалить логи"}]}],"image":"img/course-art.svg"}$content$::jsonb) on conflict (id) do update set title=excluded.title, image=excluded.image, content=excluded.content;
insert into learning_private.answer_keys (course_id, lesson_answers, exam_answers) values ('microsoft-azure-essentials', '[[0],[0],[0]]'::jsonb, '[0,0,0,0,0]'::jsonb) on conflict (course_id) do update set lesson_answers=excluded.lesson_answers, exam_answers=excluded.exam_answers;
insert into public.learning_courses (id, title, image, content) values ('introduction-to-ms-excel', 'Introduction to MS Excel', 'img/course-art.svg', $content${"id":"introduction-to-ms-excel","title":{"en":"Introduction to MS Excel","ru":"Введение в Microsoft Excel"},"description":{"en":"Use cell references, formulas, filters and summaries.","ru":"Используйте ссылки на ячейки, формулы, фильтры и сводные данные."},"icon":"XL","minutes":60,"version":1,"lessons":[{"title":{"en":"Cells and references","ru":"Ячейки и ссылки"},"paragraphs":[{"en":"A workbook contains worksheets. Cells are addressed by column and row, such as A1. Formulas start with an equals sign.","ru":"Книга состоит из листов. Адрес ячейки включает столбец и строку, например A1. Формулы начинаются со знака равенства."},{"en":"A relative reference changes when copied. An absolute reference such as $B$1 stays fixed. Your application locale may use localized function names and separators.","ru":"Относительная ссылка меняется при копировании, абсолютная $B$1 остаётся фиксированной. Названия функций и разделители зависят от языка приложения."}],"code":"A2: quantity\nB2: price\nC2: =A2*B2\nD2: =C2*$B$1","task":{"en":"Build three order rows and one shared tax-rate cell. Copy a formula while keeping the tax-rate reference fixed.","ru":"Создайте три заказа и общую ячейку ставки налога. Скопируйте формулу с фиксированной ссылкой на ставку."},"quiz":{"question":{"en":"Which reference remains fixed when copied?","ru":"Какая ссылка фиксирована при копировании?"},"options":[{"en":"B1","ru":"B1"},{"en":"$B$1","ru":"$B$1"},{"en":"B2","ru":"B2"}],"explanation":{"en":"Dollar signs fix the row and column.","ru":"Знаки доллара фиксируют строку и столбец."}}},{"title":{"en":"Functions and conditions","ru":"Функции и условия"},"paragraphs":[{"en":"SUM adds numbers and AVERAGE computes the arithmetic mean. A range such as C2:C10 includes both endpoints.","ru":"SUM суммирует числа, AVERAGE вычисляет среднее. Диапазон C2:C10 включает обе крайние ячейки."},{"en":"IF chooses one result when a condition is true and another when false. Check data types: a number stored as text may not behave like a numeric value.","ru":"IF выбирает результат по истинности условия. Проверяйте типы: число в виде текста может вести себя не как числовое значение."}],"code":"=SUM(C2:C10)\n=AVERAGE(C2:C10)\n=IF(C2>=100,\"Large\",\"Small\")\n// Russian names: СУММ, СРЗНАЧ, ЕСЛИ","task":{"en":"Calculate the total and average order size. Add a column that marks orders above your threshold.","ru":"Посчитайте сумму и средний размер заказа. Добавьте признак заказов выше выбранного порога."},"quiz":{"question":{"en":"Which function calculates a total?","ru":"Какая функция вычисляет сумму?"},"options":[{"en":"SUM / СУММ","ru":"SUM / СУММ"},{"en":"AVERAGE / СРЗНАЧ","ru":"AVERAGE / СРЗНАЧ"},{"en":"IF / ЕСЛИ","ru":"IF / ЕСЛИ"}],"explanation":{"en":"SUM adds values in a range.","ru":"SUM суммирует значения диапазона."}}},{"title":{"en":"Sort, filter and summarize","ru":"Сортировка, фильтр и сводка"},"paragraphs":[{"en":"Sorting reorders rows; filtering hides rows that do not match a condition. Keep a complete table selected so related row values stay together.","ru":"Сортировка меняет порядок строк, фильтр скрывает неподходящие строки. Выбирайте всю таблицу, чтобы связанные значения не разъехались."},{"en":"A pivot table groups records and summarizes measures, such as total sales by category. Check the source range and refresh it after data changes.","ru":"Сводная таблица группирует записи и вычисляет показатели, например продажи по категориям. Проверяйте диапазон источника и обновляйте сводку после изменений."}],"code":"Source columns: Date | Category | Amount\nPivot rows: Category\nPivot values: Sum of Amount","task":{"en":"Create a summary of sales by category and check that its grand total matches the source total.","ru":"Создайте сводку продаж по категориям и проверьте общий итог по исходным данным."},"quiz":{"question":{"en":"What does a filter do?","ru":"Что делает фильтр?"},"options":[{"en":"Deletes every hidden row","ru":"Удаляет все скрытые строки"},{"en":"Hides nonmatching rows","ru":"Скрывает неподходящие строки"},{"en":"Changes the font only","ru":"Только меняет шрифт"}],"explanation":{"en":"Filtering hides rows without deleting source data.","ru":"Фильтр скрывает строки, не удаляя исходные данные."}}}],"exam":[{"question":{"en":"Which reference remains fixed when copied?","ru":"Какая ссылка фиксирована при копировании?"},"options":[{"en":"B1","ru":"B1"},{"en":"$B$1","ru":"$B$1"},{"en":"B2","ru":"B2"}]},{"question":{"en":"Which function calculates a total?","ru":"Какая функция вычисляет сумму?"},"options":[{"en":"SUM / СУММ","ru":"SUM / СУММ"},{"en":"AVERAGE / СРЗНАЧ","ru":"AVERAGE / СРЗНАЧ"},{"en":"IF / ЕСЛИ","ru":"IF / ЕСЛИ"}]},{"question":{"en":"What does a filter do?","ru":"Что делает фильтр?"},"options":[{"en":"Deletes every hidden row","ru":"Удаляет все скрытые строки"},{"en":"Hides nonmatching rows","ru":"Скрывает неподходящие строки"},{"en":"Changes the font only","ru":"Только меняет шрифт"}]},{"question":{"en":"What begins an Excel formula?","ru":"С чего начинается формула Excel?"},"options":[{"en":"=","ru":"="},{"en":"#","ru":"#"},{"en":"@ only","ru":"Только @"}]},{"question":{"en":"When should you refresh a pivot table?","ru":"Когда нужно обновлять сводную таблицу?"},"options":[{"en":"After source data changes","ru":"После изменения источника"},{"en":"Never","ru":"Никогда"},{"en":"Only when changing fonts","ru":"Только при смене шрифта"}]}],"image":"img/course-art.svg"}$content$::jsonb) on conflict (id) do update set title=excluded.title, image=excluded.image, content=excluded.content;
insert into learning_private.answer_keys (course_id, lesson_answers, exam_answers) values ('introduction-to-ms-excel', '[[1],[0],[1]]'::jsonb, '[1,0,1,0,0]'::jsonb) on conflict (course_id) do update set lesson_answers=excluded.lesson_answers, exam_answers=excluded.exam_answers;
insert into public.learning_courses (id, title, image, content) values ('statistics-for-data-science', 'Statistics For Data Science', 'img/course-art.svg', $content${"id":"statistics-for-data-science","title":{"en":"Statistics For Data Science","ru":"Статистика для анализа данных"},"description":{"en":"Describe data, interpret variation and avoid misleading conclusions.","ru":"Описывайте данные, оценивайте разброс и избегайте ошибочных выводов."},"icon":"Σ","minutes":60,"version":1,"lessons":[{"title":{"en":"Mean and median","ru":"Среднее и медиана"},"paragraphs":[{"en":"The mean is the sum divided by the number of observations. The median is the middle of sorted data; for an even count, average the two middle values.","ru":"Среднее — сумма, делённая на число наблюдений. Медиана — середина упорядоченных данных; при чётном количестве берут среднее двух центральных значений."},{"en":"Outliers can strongly affect the mean. For skewed incomes or waiting times, compare the mean and median rather than reporting only one number.","ru":"Выбросы сильно влияют на среднее. Для асимметричных доходов или времени ожидания сравнивайте среднее и медиану."}],"code":"Data: 2, 3, 4, 5, 100\nMean: 114 / 5 = 22.8\nMedian: 4","task":{"en":"Compute the mean and median of [1, 2, 3, 4, 40]. Explain their difference.","ru":"Посчитайте среднее и медиану [1, 2, 3, 4, 40]. Объясните различие."},"quiz":{"question":{"en":"What is the median of 2, 3, 4, 5, 100?","ru":"Какова медиана 2, 3, 4, 5, 100?"},"options":[{"en":"22.8","ru":"22,8"},{"en":"4","ru":"4"},{"en":"100","ru":"100"}],"explanation":{"en":"The central sorted value is 4.","ru":"Центральное значение после сортировки — 4."}}},{"title":{"en":"Spread and samples","ru":"Разброс и выборки"},"paragraphs":[{"en":"Variance measures squared deviations from the mean. Standard deviation is its square root and uses the same units as the original values.","ru":"Дисперсия измеряет квадраты отклонений от среднего. Стандартное отклонение — её корень, в единицах исходных данных."},{"en":"A sample represents a population only if the sampling process is appropriate. A very large biased sample can still lead to poor conclusions.","ru":"Выборка представляет генеральную совокупность только при корректном отборе. Даже очень большая смещённая выборка может привести к неверным выводам."}],"code":"Group A: 9, 10, 11\nGroup B: 0, 10, 20\nBoth means: 10\nGroup B has greater spread.","task":{"en":"Compare these two groups. Describe why equal means do not imply similar distributions.","ru":"Сравните группы. Объясните, почему одинаковые средние не означают похожие распределения."},"quiz":{"question":{"en":"Which group has greater spread?","ru":"У какой группы больше разброс?"},"options":[{"en":"9, 10, 11","ru":"9, 10, 11"},{"en":"0, 10, 20","ru":"0, 10, 20"},{"en":"They are equal","ru":"Одинаковый"}],"explanation":{"en":"The second group has larger deviations from the mean.","ru":"Во второй группе отклонения от среднего больше."}}},{"title":{"en":"Correlation and conclusions","ru":"Корреляция и выводы"},"paragraphs":[{"en":"Correlation measures an association between variables. It does not show that one variable causes the other; a third factor may affect both.","ru":"Корреляция измеряет связь переменных. Она не доказывает причинность: третий фактор может влиять на обе."},{"en":"Separate exploratory findings from confirmed hypotheses. Consider sample size, uncertainty and confounding factors before making a decision.","ru":"Отличайте предварительные находки от подтверждённых гипотез. Учитывайте размер выборки, неопределённость и смешивающие факторы."}],"code":"Observation: ice-cream sales and swimming increase together.\nPossible common cause: warm weather.\nConclusion: association alone does not prove causation.","task":{"en":"Give an example of two correlated variables with a plausible common cause.","ru":"Приведите пример двух связанных переменных с возможной общей причиной."},"quiz":{"question":{"en":"Does correlation alone prove causation?","ru":"Доказывает ли корреляция причинность?"},"options":[{"en":"Yes","ru":"Да"},{"en":"No","ru":"Нет"},{"en":"If a chart is colorful","ru":"Если график цветной"}],"explanation":{"en":"Association alone does not establish a causal link.","ru":"Одна связь не устанавливает причинность."}}}],"exam":[{"question":{"en":"What is the median of 2, 3, 4, 5, 100?","ru":"Какова медиана 2, 3, 4, 5, 100?"},"options":[{"en":"22.8","ru":"22,8"},{"en":"4","ru":"4"},{"en":"100","ru":"100"}]},{"question":{"en":"Which group has greater spread?","ru":"У какой группы больше разброс?"},"options":[{"en":"9, 10, 11","ru":"9, 10, 11"},{"en":"0, 10, 20","ru":"0, 10, 20"},{"en":"They are equal","ru":"Одинаковый"}]},{"question":{"en":"Does correlation alone prove causation?","ru":"Доказывает ли корреляция причинность?"},"options":[{"en":"Yes","ru":"Да"},{"en":"No","ru":"Нет"},{"en":"If a chart is colorful","ru":"Если график цветной"}]},{"question":{"en":"What units does standard deviation use?","ru":"В каких единицах стандартное отклонение?"},"options":[{"en":"The original data units","ru":"В единицах исходных данных"},{"en":"Always percentages","ru":"Всегда проценты"},{"en":"No units ever","ru":"Всегда без единиц"}]},{"question":{"en":"Can a large biased sample mislead?","ru":"Может ли большая смещённая выборка вводить в заблуждение?"},"options":[{"en":"Yes","ru":"Да"},{"en":"No","ru":"Нет"},{"en":"Only with odd counts","ru":"Только при нечётном количестве"}]}],"image":"img/course-art.svg"}$content$::jsonb) on conflict (id) do update set title=excluded.title, image=excluded.image, content=excluded.content;
insert into learning_private.answer_keys (course_id, lesson_answers, exam_answers) values ('statistics-for-data-science', '[[1],[1],[1]]'::jsonb, '[1,1,1,0,0]'::jsonb) on conflict (course_id) do update set lesson_answers=excluded.lesson_answers, exam_answers=excluded.exam_answers;
insert into public.learning_courses (id, title, image, content) values ('java-programming', 'Java Programming', 'img/course-art.svg', $content${"id":"java-programming","title":{"en":"Java Programming","ru":"Программирование на Java"},"description":{"en":"Learn Java types, control flow, methods and objects.","ru":"Изучите типы Java, управление потоком, методы и объекты."},"icon":"Java","minutes":60,"version":1,"lessons":[{"title":{"en":"Types and entry point","ru":"Типы и точка входа"},"paragraphs":[{"en":"Java is statically typed: variables have declared types. int holds whole numbers, double holds floating-point values, and String holds text.","ru":"Java имеет статическую типизацию: тип переменной объявляется явно. int хранит целые числа, double — дробные, String — текст."},{"en":"A basic console program starts in main. Place the public class in a file with the same name, then compile and run it using a JDK.","ru":"Простая консольная программа начинается в main. Публичный класс помещают в файл с таким же именем, компилируют и запускают с помощью JDK."}],"code":"public class Main {\n public static void main(String[] args) {\n  int age = 20;\n  System.out.println(age + 1);\n }\n}","task":{"en":"Save Main.java, compile with javac Main.java, and run java Main. Change the printed expression.","ru":"Сохраните Main.java, выполните javac Main.java и java Main. Измените выводимое выражение."},"quiz":{"question":{"en":"Which type stores whole numbers?","ru":"Какой тип хранит целые числа?"},"options":[{"en":"String","ru":"String"},{"en":"int","ru":"int"},{"en":"boolean","ru":"boolean"}],"explanation":{"en":"int stores integer values.","ru":"int хранит целые значения."}}},{"title":{"en":"Loops and methods","ru":"Циклы и методы"},"paragraphs":[{"en":"Use if for conditional branches and for to repeat a block. A method declares parameters and a return type.","ru":"if задаёт условные ветви, for повторяет блок. Метод объявляет параметры и тип возвращаемого значения."},{"en":"A loop such as i < 3 visits 0, 1 and 2 when it starts at zero. Keep boundaries clear to avoid off-by-one errors.","ru":"Цикл с i < 3 при старте с нуля обрабатывает 0, 1 и 2. Проверяйте границы, чтобы не ошибиться на один шаг."}],"code":"static int square(int value) { return value * value; }\n// inside main:\nfor (int i = 0; i < 3; i++) {\n System.out.println(square(i));\n}","task":{"en":"Create a method that doubles a number and call it in a loop for values 1 through 5.","ru":"Создайте метод удвоения числа и вызовите его в цикле для 1–5."},"quiz":{"question":{"en":"What values does i take for i = 0; i < 3; i++?","ru":"Какие значения принимает i в i = 0; i < 3; i++?"},"options":[{"en":"0, 1, 2","ru":"0, 1, 2"},{"en":"1, 2, 3","ru":"1, 2, 3"},{"en":"0, 1, 2, 3","ru":"0, 1, 2, 3"}],"explanation":{"en":"The condition excludes 3.","ru":"Условие исключает значение 3."}}},{"title":{"en":"Objects and strings","ru":"Объекты и строки"},"paragraphs":[{"en":"A class defines fields and behavior; an object is an instance. A constructor initializes the instance.","ru":"Класс задаёт поля и поведение, объект — экземпляр класса. Конструктор инициализирует экземпляр."},{"en":"Use equals to compare String contents. The == operator compares object references, so it is not a reliable way to compare separately created strings by text.","ru":"Для сравнения содержимого String используйте equals. == сравнивает ссылки объектов, поэтому не подходит для сравнения текста отдельно созданных строк."}],"code":"class Student {\n String name;\n Student(String name) { this.name = name; }\n}\n// inside main:\nStudent student = new Student(\"Alex\");\nSystem.out.println(student.name.equals(\"Alex\"));","task":{"en":"Add a score field to Student and initialize it in the constructor.","ru":"Добавьте Student поле score и задайте его в конструкторе."},"quiz":{"question":{"en":"How should String contents be compared?","ru":"Как сравнивать содержимое String?"},"options":[{"en":"Always with ==","ru":"Всегда через =="},{"en":"With equals","ru":"Через equals"},{"en":"With + only","ru":"Только через +"}],"explanation":{"en":"equals compares content for strings.","ru":"equals сравнивает содержимое строк."}}}],"exam":[{"question":{"en":"Which type stores whole numbers?","ru":"Какой тип хранит целые числа?"},"options":[{"en":"String","ru":"String"},{"en":"int","ru":"int"},{"en":"boolean","ru":"boolean"}]},{"question":{"en":"What values does i take for i = 0; i < 3; i++?","ru":"Какие значения принимает i в i = 0; i < 3; i++?"},"options":[{"en":"0, 1, 2","ru":"0, 1, 2"},{"en":"1, 2, 3","ru":"1, 2, 3"},{"en":"0, 1, 2, 3","ru":"0, 1, 2, 3"}]},{"question":{"en":"How should String contents be compared?","ru":"Как сравнивать содержимое String?"},"options":[{"en":"Always with ==","ru":"Всегда через =="},{"en":"With equals","ru":"Через equals"},{"en":"With + only","ru":"Только через +"}]},{"question":{"en":"What initializes a new instance?","ru":"Что инициализирует новый экземпляр?"},"options":[{"en":"A constructor","ru":"Конструктор"},{"en":"A CSS selector","ru":"Селектор CSS"},{"en":"A file extension","ru":"Расширение файла"}]},{"question":{"en":"What is the file name for public class Main?","ru":"Как называется файл public class Main?"},"options":[{"en":"Main.java","ru":"Main.java"},{"en":"main.py","ru":"main.py"},{"en":"index.html","ru":"index.html"}]}],"image":"img/course-art.svg"}$content$::jsonb) on conflict (id) do update set title=excluded.title, image=excluded.image, content=excluded.content;
insert into learning_private.answer_keys (course_id, lesson_answers, exam_answers) values ('java-programming', '[[1],[0],[1]]'::jsonb, '[1,0,1,0,0]'::jsonb) on conflict (course_id) do update set lesson_answers=excluded.lesson_answers, exam_answers=excluded.exam_answers;
insert into public.learning_courses (id, title, image, content) values ('c-for-beginners', 'C for Beginners', 'img/course-art.svg', $content${"id":"c-for-beginners","title":{"en":"C for Beginners","ru":"C для начинающих"},"description":{"en":"Understand C variables, loops, functions and array boundaries.","ru":"Изучите переменные C, циклы, функции и границы массивов."},"icon":"C","minutes":60,"version":1,"lessons":[{"title":{"en":"Program structure","ru":"Структура программы"},"paragraphs":[{"en":"C programs use typed variables and compile to executable code. The main function is the usual entry point for a hosted console program.","ru":"C использует типизированные переменные и компилируется в исполняемый код. main — обычная точка входа консольной программы."},{"en":"Include stdio.h for printf. A format specifier must match the value type: %d prints an int. A return value of zero from main indicates success.","ru":"Для printf подключите stdio.h. Формат должен соответствовать типу: %d выводит int. Возврат нуля из main обозначает успех."}],"code":"#include <stdio.h>\nint main(void) {\n int count = 3;\n printf(\"Count: %d\\n\", count);\n return 0;\n}","task":{"en":"Compile with a C compiler and change count. Explain the purpose of %d.","ru":"Скомпилируйте программу компилятором C и измените count. Объясните назначение %d."},"quiz":{"question":{"en":"Which header declares printf?","ru":"Какой заголовок объявляет printf?"},"options":[{"en":"stdio.h","ru":"stdio.h"},{"en":"html.h","ru":"html.h"},{"en":"styles.css","ru":"styles.css"}],"explanation":{"en":"printf is declared in stdio.h.","ru":"printf объявлен в stdio.h."}}},{"title":{"en":"Control flow and functions","ru":"Управление потоком и функции"},"paragraphs":[{"en":"Use if to choose a branch and for to repeat work. A function declaration specifies its return type and parameters.","ru":"if выбирает ветвь, for повторяет работу. Объявление функции задаёт тип результата и параметры."},{"en":"Integer division discards the fractional part: 5 / 2 yields 2 with integer operands. Use floating-point operands when a fractional result is needed.","ru":"Целочисленное деление отбрасывает дробную часть: 5 / 2 даёт 2. Для дробного результата нужны операнды с плавающей точкой."}],"code":"int double_value(int value) { return value * 2; }\n// inside main:\nfor (int i = 0; i < 3; i++) {\n printf(\"%d\\n\", double_value(i));\n}","task":{"en":"Write a function that returns the larger of two integers.","ru":"Напишите функцию, возвращающую большее из двух целых чисел."},"quiz":{"question":{"en":"What is 5 / 2 with integer operands in C?","ru":"Чему равно 5 / 2 с целыми операндами в C?"},"options":[{"en":"2","ru":"2"},{"en":"2.5","ru":"2,5"},{"en":"5","ru":"5"}],"explanation":{"en":"Integer division discards the fractional part.","ru":"Целочисленное деление отбрасывает дробную часть."}}},{"title":{"en":"Arrays and memory boundaries","ru":"Массивы и границы памяти"},"paragraphs":[{"en":"An array has a fixed number of elements and uses zero-based indexes. For an array of length 3, valid indexes are 0, 1 and 2.","ru":"Массив имеет фиксированное число элементов, индексы начинаются с нуля. Для длины 3 допустимы 0, 1 и 2."},{"en":"C does not automatically check every array access. Reading or writing outside a boundary has undefined behavior. A string needs room for a terminating null character.","ru":"C не проверяет автоматически каждое обращение к массиву. Выход за границы приводит к неопределённому поведению. Строке нужно место для завершающего нулевого символа."}],"code":"int values[3] = {10, 20, 30};\nfor (int i = 0; i < 3; i++) {\n printf(\"%d\\n\", values[i]);\n}\nchar name[] = \"Alex\"; // includes a null terminator","task":{"en":"Find why i <= 3 would be incorrect in this loop. Count the bytes needed for \"Alex\" including its terminator.","ru":"Объясните ошибку i <= 3 в цикле. Посчитайте байты для \"Alex\" с завершающим символом."},"quiz":{"question":{"en":"What is the last valid index of int values[3]?","ru":"Какой последний допустимый индекс int values[3]?"},"options":[{"en":"3","ru":"3"},{"en":"2","ru":"2"},{"en":"4","ru":"4"}],"explanation":{"en":"Zero-based indexes end at length minus one.","ru":"Индексы с нуля заканчиваются на длина минус один."}}}],"exam":[{"question":{"en":"Which header declares printf?","ru":"Какой заголовок объявляет printf?"},"options":[{"en":"stdio.h","ru":"stdio.h"},{"en":"html.h","ru":"html.h"},{"en":"styles.css","ru":"styles.css"}]},{"question":{"en":"What is 5 / 2 with integer operands in C?","ru":"Чему равно 5 / 2 с целыми операндами в C?"},"options":[{"en":"2","ru":"2"},{"en":"2.5","ru":"2,5"},{"en":"5","ru":"5"}]},{"question":{"en":"What is the last valid index of int values[3]?","ru":"Какой последний допустимый индекс int values[3]?"},"options":[{"en":"3","ru":"3"},{"en":"2","ru":"2"},{"en":"4","ru":"4"}]},{"question":{"en":"What does return 0 in main usually indicate?","ru":"Что обычно означает return 0 в main?"},"options":[{"en":"Successful execution","ru":"Успешное выполнение"},{"en":"An infinite loop","ru":"Бесконечный цикл"},{"en":"A missing header","ru":"Отсутствующий заголовок"}]},{"question":{"en":"What extra character ends a C string?","ru":"Какой дополнительный символ завершает строку C?"},"options":[{"en":"A null terminator","ru":"Нулевой символ"},{"en":"Always a space","ru":"Всегда пробел"},{"en":"A tab","ru":"Табуляция"}]}],"image":"img/course-art.svg"}$content$::jsonb) on conflict (id) do update set title=excluded.title, image=excluded.image, content=excluded.content;
insert into learning_private.answer_keys (course_id, lesson_answers, exam_answers) values ('c-for-beginners', '[[0],[0],[1]]'::jsonb, '[0,0,1,0,0]'::jsonb) on conflict (course_id) do update set lesson_answers=excluded.lesson_answers, exam_answers=excluded.exam_answers;
